-- Durable, explicit opt-in analysis. Models are part of the document identity.
create table public.atlas_ai_settings(
 owner_id uuid primary key references auth.users(id) on delete cascade,enabled boolean not null default false,
 excluded_space_ids text[] not null default '{}'
);
create table public.analysis_jobs(
 id uuid primary key default gen_random_uuid(),owner_id uuid not null,item_id uuid not null,input_revision bigint not null,
 model text not null check(length(model) between 1 and 300),embedding_model text not null check(length(embedding_model) between 1 and 200),
 status text not null default 'queued' check(status in ('queued','running','done','failed','stale','cancelled')),
 attempts integer not null default 0,token uuid,lease_until timestamptz,next_retry_at timestamptz not null default now(),error_code text,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(owner_id,item_id,input_revision,model,embedding_model),foreign key(owner_id,item_id) references public.items(owner_id,id) on delete cascade
);
create index analysis_jobs_queue on public.analysis_jobs(status,next_retry_at,created_at);
create index analysis_jobs_item on public.analysis_jobs(owner_id,item_id);
create table public.search_documents(
 owner_id uuid not null,item_id uuid not null,input_revision bigint not null,model text not null,embedding_model text not null,
 caption text not null,ocr text not null,suggestions jsonb not null,normalized_text text not null,
 embedding double precision[] not null,dimensions integer not null check(dimensions between 1 and 8192),
 updated_at timestamptz not null default now(),primary key(owner_id,item_id),
 check(array_length(embedding,1)=dimensions),foreign key(owner_id,item_id) references public.items(owner_id,id) on delete cascade
);
