create function private.configure_atlas_ai(p_enabled boolean,p_excluded text[]) returns void language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();s text;
begin
 if u is null then raise exception 'Sign in required' using errcode='42501';end if;
 if p_enabled is null or p_excluded is null or cardinality(p_excluded)>1000 then raise exception 'Invalid settings' using errcode='22023';end if;
 foreach s in array p_excluded loop
  if s is null or not exists(select 1 from public.spaces where owner_id=u and id=s) then raise exception 'Space not found' using errcode='23503';end if;
 end loop;
 insert into public.atlas_ai_settings values(u,p_enabled,p_excluded) on conflict(owner_id) do update set enabled=excluded.enabled,excluded_space_ids=excluded.excluded_space_ids;
 update public.analysis_jobs j set status='cancelled',token=null,updated_at=now() where j.owner_id=u and j.status in ('queued','running','failed')
  and (not p_enabled or exists(select 1 from public.item_spaces x where x.owner_id=u and x.item_id=j.item_id and x.space_id=any(p_excluded)));
 delete from public.search_documents d where d.owner_id=u and (not p_enabled or exists(select 1 from public.item_spaces x where x.owner_id=u and x.item_id=d.item_id and x.space_id=any(p_excluded)));
end;
$$;
create function private.enqueue_atlas_analysis(p_item uuid,p_model text,p_embedding_model text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();v bigint;j uuid;
begin
 if u is null then raise exception 'Sign in required' using errcode='42501';end if;
 if p_model is null or length(p_model) not between 1 and 300 or p_embedding_model is null or length(p_embedding_model) not between 1 and 200 then raise exception 'Models required' using errcode='22023';end if;
 perform 1 from public.atlas_ai_settings where owner_id=u and enabled for share;
 if not found then raise exception 'AI consent required' using errcode='42501';end if;
 select revision into v from public.items where owner_id=u and id=p_item and deleted_at is null for share;
 if not found then raise exception 'Item not found' using errcode='23503';end if;
 if exists(select 1 from public.item_spaces x join public.atlas_ai_settings a on a.owner_id=x.owner_id where x.owner_id=u and x.item_id=p_item and x.space_id=any(a.excluded_space_ids)) then raise exception 'Excluded space' using errcode='42501';end if;
 if (select count(*) from public.analysis_jobs where owner_id=u and status in ('queued','running'))>=100 then raise exception 'Queue full' using errcode='54000';end if;
 -- A model switch immediately removes previous results, including same-dimension vectors.
 delete from public.search_documents where owner_id=u and item_id=p_item;
 update public.analysis_jobs set status='stale',token=null where owner_id=u and item_id=p_item and (input_revision<>v or model<>p_model or embedding_model<>p_embedding_model) and status in ('queued','running','failed');
 insert into public.analysis_jobs(owner_id,item_id,input_revision,model,embedding_model) values(u,p_item,v,p_model,p_embedding_model)
 on conflict(owner_id,item_id,input_revision,model,embedding_model) do update set status=case when public.analysis_jobs.status='running' then 'running' else 'queued' end,
 attempts=case when public.analysis_jobs.status='running' then public.analysis_jobs.attempts else 0 end,next_retry_at=now(),error_code=null,updated_at=now() returning id into j;
 return j;
end;
$$;

-- Any revision change invalidates AI text and vectors in the same transaction.
create function private.invalidate_atlas_analysis() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.revision<>old.revision or new.deleted_at is distinct from old.deleted_at then
  delete from public.search_documents where owner_id=new.owner_id and item_id=new.id;
  update public.analysis_jobs set status='stale',token=null,updated_at=now() where owner_id=new.owner_id and item_id=new.id and status in ('queued','running','failed');
 end if;
 return new;
end;
$$;
create trigger invalidate_atlas_analysis after update on public.items for each row execute function private.invalidate_atlas_analysis();
revoke all on function private.invalidate_atlas_analysis() from public,anon,authenticated;

-- Only a server worker holding service_role can lease/complete jobs. It never
-- accepts an owner supplied by a browser; the owner comes from the persisted job.
create function private.claim_atlas_analysis(p_model text,p_embedding_model text) returns jsonb language plpgsql security definer set search_path='' as $$
declare j public.analysis_jobs%rowtype;payload jsonb;
begin
 update public.analysis_jobs set status='failed',token=null,error_code='lease_expired',updated_at=now()
 where model=p_model and embedding_model=p_embedding_model and status='running' and lease_until<now() and attempts>=3;
 select q.* into j from public.analysis_jobs q join public.items i on i.owner_id=q.owner_id and i.id=q.item_id
 join public.atlas_ai_settings a on a.owner_id=q.owner_id and a.enabled
 where q.model=p_model and q.embedding_model=p_embedding_model and i.deleted_at is null and i.revision=q.input_revision and q.attempts<3
 and ((q.status in ('queued','failed') and q.next_retry_at<=now()) or (q.status='running' and q.lease_until<now()))
 and not exists(select 1 from public.item_spaces x where x.owner_id=q.owner_id and x.item_id=q.item_id and x.space_id=any(a.excluded_space_ids))
 order by q.created_at limit 1 for update of q skip locked;
 if not found then return null;end if;
 update public.analysis_jobs set status='running',attempts=attempts+1,token=gen_random_uuid(),lease_until=now()+interval '5 minutes',updated_at=now() where id=j.id returning * into j;
 select case i.kind when 'note' then private._sync_note(i.owner_id,i.id) when 'sketch' then private._sync_sketch(i.owner_id,i.id) else private._sync_resource(i.owner_id,i.id) end into payload from public.items i where i.owner_id=j.owner_id and i.id=j.item_id;
 return jsonb_build_object('id',j.id,'ownerId',j.owner_id,'itemId',j.item_id,'inputRevision',j.input_revision,'token',j.token,'item',payload);
end;
$$;
create function private.finish_atlas_analysis(p_job uuid,p_token uuid,p_result jsonb,p_error text default null) returns boolean language plpgsql security definer set search_path='' as $$
declare j public.analysis_jobs%rowtype;vec double precision[];dim integer;
begin
 -- Read identity, then lock settings -> item -> job, matching enqueue and the
 -- item invalidation trigger. Never hold a job while waiting on its item.
 select * into j from public.analysis_jobs where id=p_job and token=p_token and status='running' and lease_until>now();
 if not found then return false;end if;
 perform 1 from public.atlas_ai_settings where owner_id=j.owner_id and enabled for share;
 if not found then return false;end if;
 perform 1 from public.items where owner_id=j.owner_id and id=j.item_id and deleted_at is null and revision=j.input_revision for share;
 if not found or exists(select 1 from public.item_spaces x join public.atlas_ai_settings a on a.owner_id=x.owner_id where x.owner_id=j.owner_id and x.item_id=j.item_id and x.space_id=any(a.excluded_space_ids)) then
  update public.analysis_jobs set status='stale',token=null,updated_at=now() where id=j.id;return false;
 end if;
 select * into j from public.analysis_jobs where id=p_job and token=p_token and status='running' and lease_until>now() for update;
 if not found then return false;end if;
 if p_error is not null then
  update public.analysis_jobs set status='failed',token=null,error_code='provider_failed',next_retry_at=now()+interval '1 minute'*power(2,attempts),updated_at=now() where id=j.id;return false;
 end if;
 if jsonb_typeof(p_result->'caption') is distinct from 'string' or length(p_result->>'caption')>4000 or jsonb_typeof(p_result->'ocr') is distinct from 'string' or length(p_result->>'ocr')>12000
 or jsonb_typeof(p_result->'text') is distinct from 'string' or length(p_result->>'text')>24000 or jsonb_typeof(p_result->'suggestions') is distinct from 'array' or jsonb_array_length(p_result->'suggestions')>20
 or exists(select 1 from jsonb_array_elements(p_result->'suggestions') s where jsonb_typeof(s)<>'string' or length(btrim(s#>>'{}')) not between 1 and 40)
 or jsonb_typeof(p_result->'embedding') is distinct from 'array' or jsonb_array_length(p_result->'embedding') not between 1 and 8192
 or exists(select 1 from jsonb_array_elements(p_result->'embedding') v where jsonb_typeof(v)<>'number') then raise exception 'Invalid analysis' using errcode='22023';end if;
 select array_agg(value::double precision) into vec from jsonb_array_elements_text(p_result->'embedding');dim:=cardinality(vec);
 if exists(select 1 from unnest(vec) v where v is null or v not between -1e10 and 1e10) or (select sum(v*v) from unnest(vec) v)<=0 then raise exception 'Invalid vector' using errcode='22023';end if;
 insert into public.search_documents(owner_id,item_id,input_revision,model,embedding_model,caption,ocr,suggestions,normalized_text,embedding,dimensions)
 values(j.owner_id,j.item_id,j.input_revision,j.model,j.embedding_model,p_result->>'caption',p_result->>'ocr',p_result->'suggestions',p_result->>'text',vec,dim)
 on conflict(owner_id,item_id) do update set input_revision=excluded.input_revision,model=excluded.model,embedding_model=excluded.embedding_model,caption=excluded.caption,ocr=excluded.ocr,suggestions=excluded.suggestions,normalized_text=excluded.normalized_text,embedding=excluded.embedding,dimensions=excluded.dimensions,updated_at=now();
 update public.analysis_jobs set status='done',token=null,error_code=null,updated_at=now() where id=j.id;return true;
end;
$$;
create function private.atlas_cosine(a double precision[],b double precision[]) returns double precision language sql immutable strict set search_path='' as $$
 select sum(x*y)/nullif(sqrt(sum(x*x))*sqrt(sum(y*y)),0) from unnest(a,b) v(x,y);
$$;
create function public.match_atlas_documents(p_vector double precision[],p_model text,p_embedding_model text,p_kind text default null,p_space text default null,p_tag text default null,p_project uuid default null,p_limit integer default 30)
returns table(item_id uuid,input_revision bigint,score double precision) language plpgsql stable security invoker set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'Sign in required' using errcode='42501';end if;
 if cardinality(p_vector) is null or cardinality(p_vector) not between 1 and 8192 or exists(select 1 from unnest(p_vector) v where v is null or v not between -1e10 and 1e10)
 or (select sum(v*v) from unnest(p_vector) v)<=0 then raise exception 'Invalid query vector' using errcode='22023';end if;
 return query
 with eligible as materialized (
 select d.* from public.search_documents d join public.items i on i.owner_id=d.owner_id and i.id=d.item_id and i.revision=d.input_revision and i.deleted_at is null
 join public.atlas_ai_settings a on a.owner_id=d.owner_id and a.enabled
 where d.owner_id=(select auth.uid()) and d.model=p_model and d.embedding_model=p_embedding_model and d.dimensions=cardinality(p_vector)
 and (p_kind is null or i.kind=p_kind)
 and (p_space is null or exists(select 1 from public.item_spaces x where x.owner_id=d.owner_id and x.item_id=d.item_id and x.space_id=p_space))
 and not exists(select 1 from public.item_spaces x where x.owner_id=d.owner_id and x.item_id=d.item_id and x.space_id=any(a.excluded_space_ids))
 and (p_tag is null or exists(select 1 from public.item_labels l where l.owner_id=d.owner_id and l.item_id=d.item_id and l.deleted_at is null and l.tags ? p_tag))
 and (p_project is null or exists(select 1 from public.project_items x join public.projects p on p.owner_id=x.owner_id and p.id=x.project_id and p.deleted_at is null where x.owner_id=d.owner_id and x.item_id=d.item_id and x.project_id=p_project))
 ) select e.item_id,e.input_revision,private.atlas_cosine(e.embedding,p_vector) as score from eligible e order by score desc,e.item_id limit least(greatest(coalesce(p_limit,30),1),100);
end;
$$;

