create function private.pull_atlas_changes(p_cursor text default '0',p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare u uuid:=auth.uid();a bigint;n bigint;l integer;j jsonb;
begin
 if u is null then raise exception 'Sign in required' using errcode='42501';end if;
 if p_cursor is null or p_cursor !~ '^[0-9]{1,19}$' then raise exception 'Invalid cursor' using errcode='22023';end if;
 a:=p_cursor::bigint;l:=least(greatest(coalesce(p_limit,100),1),200);
 select coalesce(jsonb_agg(jsonb_build_object('cursor',c.cursor::text,'entity',c.entity,'record',c.record) order by c.cursor),'[]'::jsonb),coalesce(max(c.cursor),a) into j,n
  from(select * from public.sync_changes where owner_id=u and cursor>a order by cursor limit l)c;
 return jsonb_build_object('changes',j,'cursor',n::text,'hasMore',exists(select 1 from public.sync_changes where owner_id=u and cursor>n));
end;
$$;
create function public.pull_atlas_changes(p_cursor text default '0',p_limit integer default 100) returns jsonb language sql stable security invoker set search_path='' as $$select private.pull_atlas_changes(p_cursor,p_limit);$$;
