 from(select * from public.sync_changes where owner_id=u and cursor>a and entity in ('note','space','sketch','resource','relation') and (entity<>'relation' or record->>'type'='inspired_by') order by cursor limit least(greatest(coalesce(p_limit,100),1),200))c;
